#!/usr/bin/env python3
"""Generate native Traefik JSON and replay it through the production Custos image."""
import json
import http.client
import os
import pathlib
import subprocess
import tempfile
import time
import urllib.error
import urllib.request
import uuid


def docker(*args, check=True):
    return subprocess.run(["docker", *args], text=True, capture_output=True, check=check)


def main():
    name = "custos-traefik-" + uuid.uuid4().hex[:10]
    image = os.environ.get("CUSTOS_TRAEFIK_IMAGE", "traefik:v3.5")
    with tempfile.TemporaryDirectory(prefix="custos-traefik-") as directory:
        tmp = pathlib.Path(directory)
        # Replay stays entirely local: no native firewall, Hub, or external model.
        tmp.joinpath("config.toml").write_text('''
[daemon]
decisions_file = "/tmp/traefik-decisions.jsonl"
[firewall]
enabled = false
''')
        # Attach logging to an explicit router on all builds. An IP policy denies
        # the controlled probes before any backend is contacted (OriginStatus=0).
        legacy = ":v2." in image
        expected_status = 403
        policy = "ipWhiteList" if legacy else "ipAllowList"
        tmp.joinpath("routes.yml").write_text('''
http:
  routers:
    probes:
      rule: "PathPrefix(`/`)"
      entryPoints: [web]
      middlewares: [deny]
      service: unavailable
  middlewares:
    deny:
      POLICY:
        sourceRange: ["192.0.2.1/32"]
  services:
    unavailable:
      loadBalancer:
        servers:
          - url: "http://127.0.0.1:1"
'''.replace("POLICY", policy))
        provider = ["--providers.file.filename=/logs/routes.yml"]
        try:
            docker("run", "-d", "--name", name, "-p", "127.0.0.1::8000",
                   "-v", f"{directory}:/logs", image,
                   "--entrypoints.web.address=:8000", "--accesslog=true",
                   "--accesslog.format=json", "--accesslog.filepath=/logs/access.log", *provider)
            port = int(docker("inspect", "--format",
                              '{{(index (index .NetworkSettings.Ports "8000/tcp") 0).HostPort}}',
                              name).stdout.strip())
            deadline = time.monotonic() + 20
            while True:
                try:
                    urllib.request.urlopen(f"http://127.0.0.1:{port}/_custos_ready", timeout=0.5).close()
                    raise AssertionError("Unrouted readiness request unexpectedly succeeded")
                except urllib.error.HTTPError as error:
                    ready = error.code == expected_status
                    error.close()
                    if ready:
                        break
                    if time.monotonic() >= deadline:
                        raise AssertionError("Traefik router did not become ready")
                    time.sleep(0.1)
                except (urllib.error.URLError, http.client.HTTPException, OSError):
                    if time.monotonic() >= deadline:
                        raise AssertionError("Traefik did not become ready")
                    time.sleep(0.1)
            # Responses are generated by Traefik itself.
            paths = ["/microservice/.env", "/service/.env", "/api/v3/.env", "/api/dev/.env", "/api/staging/.env"]
            for path in paths:
                try:
                    urllib.request.urlopen(f"http://127.0.0.1:{port}{path}", timeout=5).close()
                    raise AssertionError("Unrouted probe unexpectedly succeeded")
                except urllib.error.HTTPError as error:
                    assert error.code == expected_status
                    error.close()
            records = []
            deadline = time.monotonic() + 5
            while time.monotonic() < deadline:
                try:
                    lines = tmp.joinpath("access.log").read_text().splitlines()
                    # Exclude readiness traffic without modifying any generated record.
                    selected = [line for line in lines if json.loads(line).get("RequestPath") in paths]
                    records = [json.loads(line) for line in selected]
                except (FileNotFoundError, json.JSONDecodeError):
                    records = []  # Wait for a complete record if Traefik is writing.
                if len(records) == 5:
                    break
                time.sleep(0.1)
            assert len(records) == 5
            assert all(r["DownstreamStatus"] == expected_status for r in records)
            assert all(r.get("OriginStatus", 0) == 0 for r in records)
            tmp.joinpath("replay.jsonl").write_text("\n".join(selected) + "\n")
            replay = docker("run", "--rm", "--network", "none", "-v", f"{directory}:/test:ro",
                            "custos:ci", "--config", "/test/config.toml", "replay",
                            "--log", "/test/replay.jsonl", "--format", "json", "--mock-jev")
            assert "5 parsed events" in replay.stdout, replay.stdout
            assert "vulnerability_scanner" in replay.stdout, replay.stdout
            assert "Jev L2 Actor Verdicts (1)" in replay.stdout, replay.stdout
            origins = sorted({r.get("OriginStatus", 0) for r in records})
            print(f"Native {image} JSON: 5/5 records parsed, downstream={expected_status}, origin={origins}, 1 scanner conviction")
        except Exception:
            logs = docker("logs", "--tail", "20", name, check=False)
            print(logs.stdout, logs.stderr)
            if tmp.joinpath("access.log").exists():
                print("Generated test log:", tmp.joinpath("access.log").read_text()[-4096:])
            raise
        finally:
            docker("rm", "-fv", name, check=False)


if __name__ == "__main__":
    main()
